kata.solucion:
export function coloresValidos() {
  return ['rojo', 'verde', 'azul'] as const;
}

type Color = (ReturnType<typeof coloresValidos>)[number];

export function esColorValido(valor: string): valor is Color {
  // El cast a readonly string[] deja usar includes con un string cualquiera.
  return (coloresValidos() as readonly string[]).includes(valor);
}
